occurrences.quote:
axios.interceptors.request.use(
  function validate(config) {
    if (!config.headers.has('Authorization')) {
      throw new Error('Authorization is required');
    }
    return config;
  },
  function rejectInvalidRequest(error) {
    return Promise.reject(error);
  },
  { synchronous: true }
);

